import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const num = (v: unknown, fallback: number): number =>
  typeof v === "number" && Number.isFinite(v) ? v : fallback;
const str = (v: unknown): string => (typeof v === "string" ? v : "");

const SplitImageText: React.FC<PrimitiveProps> = ({ anim, fps, dark }) => {
  const frame = useCurrentFrame();
  const p = anim.params ?? {};

  const src = str(p.imageSrc);
  const eyebrow = str(p.eyebrow);
  const split = Math.min(0.8, Math.max(0.2, num(p.split, 0.55)));
  const stagger = Math.max(1, Math.round(num(p.stagger, 3)));
  const words = String(anim.text ?? "").split(/\s+/).filter(Boolean);

  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const mutedColor = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;
  const bg = dark ? COLORS.ink : COLORS.papyrus;

  // Top plate: settles from a slight over-scale, so the image reads as a printed plate.
  const plate = spring({ frame, fps, config: { damping: 200 }, durationInFrames: Math.round(fps * 0.9) });
  const plateScale = interpolate(plate, [0, 1], [1.12, 1]);
  const plateOpacity = interpolate(plate, [0, 0.35], [0, 1], { extrapolateRight: "clamp" });

  const eyebrowIn = interpolate(frame, [4, 4 + Math.round(fps * 0.4)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gradientText =
    STYLE.headline === "gradient"
      ? {
          backgroundImage: headlineGradient(),
          WebkitBackgroundClip: "text" as const,
          backgroundClip: "text" as const,
          color: "transparent",
        }
      : { color: textColor };

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      {/* TOP — image plate */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: 1080,
          height: Math.round(1920 * split),
          overflow: "hidden",
          opacity: plateOpacity,
          borderBottom: `6px solid ${COLORS.teal}`,
        }}
      >
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transform: `scale(${plateScale})`,
            }}
          />
        ) : (
          // No image supplied: flat plate + halftone dots (tokens only, no hardcoded colour).
          <div
            style={{
              width: "100%",
              height: "100%",
              backgroundColor: COLORS.vellum,
              backgroundImage: `radial-gradient(${mutedColor} 1.6px, transparent 1.7px)`,
              backgroundSize: "14px 14px",
              transform: `scale(${plateScale})`,
            }}
          />
        )}
      </div>

      {/* BOTTOM — text */}
      <div
        style={{
          position: "absolute",
          top: Math.round(1920 * split),
          left: 0,
          width: 1080,
          height: 1920 - Math.round(1920 * split),
          boxSizing: "border-box",
          padding: "72px 88px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: 32,
        }}
      >
        {eyebrow ? (
          <div
            style={{
              fontFamily: FONTS.mono,
              fontSize: 26,
              fontWeight: 600,
              letterSpacing: "0.3em",
              textTransform: "uppercase",
              color: COLORS.teal,
              opacity: eyebrowIn,
              transform: `translateX(${interpolate(eyebrowIn, [0, 1], [-24, 0])}px)`,
            }}
          >
            {eyebrow}
          </div>
        ) : null}

        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: 92,
            lineHeight: 0.94,
            letterSpacing: "-0.035em",
            textTransform: STYLE.uppercaseTitles ? "uppercase" : "none",
            textShadow: STYLE.headline === "gradient" ? undefined : ENGRAVE_SHADOW,
            ...gradientText,
          }}
        >
          {words.map((w, i) => {
            const s = spring({
              frame: frame - (8 + i * stagger),
              fps,
              config: { damping: 200 },
              durationInFrames: Math.round(fps * 0.5),
            });
            return (
              <span
                key={`${w}-${i}`}
                style={{
                  display: "inline-block",
                  marginRight: "0.28em",
                  opacity: s,
                  transform: `translateY(${interpolate(s, [0, 1], [34, 0])}px)`,
                }}
              >
                {w}
              </span>
            );
          })}
        </div>

        <div
          style={{
            height: 3,
            width: `${Math.round(interpolate(plate, [0, 1], [0, 100]))}%`,
            backgroundColor: COLORS.gold,
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default SplitImageText;
